CREATE OR REPLACE FUNCTION public.region_at(p_world uuid, p_x double precision, p_y double precision)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
AS $function$
#variable_conflict use_column
begin
  return (

  select get_byte(r.cells, least(255, greatest(0, floor(p_x * 256 / w.size)::int)))
